('51000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001',0,'Microservices là cách tiếp cận kiến trúc chia hệ thống thành các dịch vụ nhỏ, độc lập tương đối và giao tiếp qua API hoặc message.',3,'demo-vector-ref-001'),
